// Şube PIN'leri (production'da environment variable veya database'den alınmalı)
const PINS = {
  'merkez': '123456',
  'sube-kadikoy': '234567',
  'sube-besiktas': '345678',
  'sube-sisli': '456789',
  'sube-uskudar': '567890',
  'sube-bakirkoy': '678901'
};

const body = $input.item.json.body;
const sube = body.sube;
const pin = body.pin;

// Validation
if (!sube || !pin) {
  throw new Error('Şube ve PIN gereklidir');
}

if (!PINS[sube]) {
  throw new Error('Geçersiz şube');
}

if (PINS[sube] !== pin) {
  throw new Error('Hatalı PIN');
}

return {
  json: {
    sube: sube,
    valid: true,
    timestamp: new Date().toISOString()
  }
};

// JWT oluşturma
// Not: Production'da jsonwebtoken paketi kullanılmalı
// Bu basitleştirilmiş bir token oluşturma örneğidir

const crypto = require('crypto');

const sube = $json.sube;
const secret = process.env.JWT_SECRET || 'CHANGE_THIS_SECRET_KEY_IN_PRODUCTION';

// Payload
const payload = {
  sube: sube,
  iat: Math.floor(Date.now() / 1000),
  exp: Math.floor(Date.now() / 1000) + (12 * 60 * 60) // 12 saat
};

// Basit token oluşturma (production'da jwt.sign kullanın)
const header = Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })).toString('base64');
const payloadStr = Buffer.from(JSON.stringify(payload)).toString('base64');
const signature = crypto.createHmac('sha256', secret)
  .update(`${header}.${payloadStr}`)
  .digest('base64');

const token = `${header}.${payloadStr}.${signature}`;

return {
  json: {
    success: true,
    token: token,
    sube: sube,
    expiresIn: '12h'
  }
};
